python3 - <<'PY'
import socket, subprocess, json
host="192.168.0.100"
port=36451
out={}
def cmd(args, timeout=5):
    try:
        p=subprocess.run(args,text=True,capture_output=True,timeout=timeout)
        return {"rc":p.returncode,"out":p.stdout.strip(),"err":p.stderr.strip()}
    except subprocess.TimeoutExpired:
        return {"timeout":True}
for iface in ("en0","en1"):
    out[f"ip_{iface}"]=cmd(["ipconfig","getifaddr",iface],2)
out["route"]=cmd(["route","-n","get",host],3)
out["arp"]=cmd(["arp","-n",host],3)
out["ping"]=cmd(["ping","-c","1","-W","1000",host],4)
try:
    s=socket.create_connection((host,port),timeout=3)
    out["tcp"]={"ok":True,"peer":str(s.getpeername())}
    s.close()
except Exception as e:
    out["tcp"]={"ok":False,"error":repr(e)}
try:
    out["android2_dns"]=socket.gethostbyname("Android-2.local")
except Exception as e:
    out["android2_dns_error"]=repr(e)
out["adb_devices"]=cmd(["adb","devices","-l"],4)
try:
    out["adb_mdns"]=cmd(["adb","mdns","services"],5)
except Exception as e:
    out["adb_mdns_error"]=repr(e)
print(json.dumps(out,indent=2))
PY

